/// Checks requests and responses against the contract. The module's API is
/// its types, the Handlers trait and the router; nothing in here is part
/// of it.
// A contract does not need every helper.
#[allow(dead_code)]
mod runtime {
    use std::collections::HashMap;
    use std::fmt::Write as _;
    use std::sync::OnceLock;

    use axum::body::Bytes;
    use axum::http::{HeaderMap, StatusCode};
    use axum::response::{IntoResponse, Response};
    use serde::de::DeserializeOwned;
    use serde::{Deserialize, Serialize};
    use serde_json::{Map, Number, Value};

    // -------------------------------------------------------------------------
    // Schemas
    // -------------------------------------------------------------------------

    /// A JSON type a schema allows.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum Type {
        Null,
        Boolean,
        Integer,
        Number,
        String,
        Array,
        Object,
    }

    impl Type {
        /// The name Zod has for it in a message.
        fn name(self) -> &'static str {
            match self {
                Type::Null => "null",
                Type::Boolean => "boolean",
                Type::Integer | Type::Number => "number",
                Type::String => "string",
                Type::Array => "array",
                Type::Object => "object",
            }
        }
    }

    /// A value a schema names: its constant, or one of its options.
    #[derive(Debug, Clone, Copy, PartialEq)]
    pub(super) enum Literal {
        Null,
        Bool(bool),
        Number(f64),
        Text(&'static str),
    }

    impl Literal {
        fn is(self, value: &Value) -> bool {
            match self {
                Literal::Null => value.is_null(),
                Literal::Bool(expected) => value.as_bool() == Some(expected),
                Literal::Number(expected) => value.as_f64() == Some(expected),
                Literal::Text(expected) => value.as_str() == Some(expected),
            }
        }

        /// The literal as JSON writes it.
        fn json(self) -> String {
            match self {
                Literal::Null => "null".into(),
                Literal::Bool(value) => value.to_string(),
                Literal::Number(value) => js_number(value),
                Literal::Text(value) => Value::from(value).to_string(),
            }
        }
    }

    /// What happens to the members of an object that its schema does not
    /// name.
    #[derive(Debug, Clone, Copy)]
    pub(super) enum Additional {
        Ignored,
        Refused,
        Each(&'static Schema),
    }

    /// What the contract says a JSON value has to be: the keywords of JSON
    /// Schema that a contract uses. A keyword that is not set does not
    /// constrain the value.
    #[derive(Debug, Clone, Copy)]
    pub(super) struct Schema {
        /// The schema this one stands for.
        pub(super) reference: Option<&'static Schema>,
        /// The types the value may have; none listed means any.
        pub(super) types: &'static [Type],
        pub(super) constant: Option<Literal>,
        pub(super) options: Option<&'static [Literal]>,
        pub(super) any_of: Option<&'static [Schema]>,
        /// The member that decides which alternative a value is: each
        /// alternative is an object that requires it, with a text
        /// constant of its own.
        pub(super) tag: Option<&'static str>,
        pub(super) all_of: Option<&'static [Schema]>,
        pub(super) min_length: Option<u64>,
        pub(super) max_length: Option<u64>,
        /// A regular expression, as JavaScript reads it.
        pub(super) pattern: Option<&'static Pattern>,
        pub(super) format: Option<&'static str>,
        pub(super) minimum: Option<f64>,
        pub(super) maximum: Option<f64>,
        pub(super) exclusive_minimum: Option<f64>,
        pub(super) exclusive_maximum: Option<f64>,
        pub(super) multiple_of: Option<f64>,
        pub(super) min_items: Option<u64>,
        pub(super) max_items: Option<u64>,
        /// The schema of every item of a list.
        pub(super) items: Option<&'static Schema>,
        /// The schemas of a tuple's items, by position.
        pub(super) prefix_items: Option<&'static [Schema]>,
        /// The members of an object, in the order the contract has them.
        pub(super) properties: Option<&'static [(&'static str, Schema)]>,
        pub(super) required: &'static [&'static str],
        pub(super) additional: Additional,
    }

    impl Schema {
        /// The schema that accepts every value.
        pub(super) const ANY: Schema = Schema {
            reference: None,
            types: &[],
            constant: None,
            options: None,
            any_of: None,
            tag: None,
            all_of: None,
            min_length: None,
            max_length: None,
            pattern: None,
            format: None,
            minimum: None,
            maximum: None,
            exclusive_minimum: None,
            exclusive_maximum: None,
            multiple_of: None,
            min_items: None,
            max_items: None,
            items: None,
            prefix_items: None,
            properties: None,
            required: &[],
            additional: Additional::Ignored,
        };

        /// The schema itself, or the one it stands for.
        fn resolved(&'static self) -> &'static Schema {
            let mut schema = self;
            while let Some(target) = schema.reference {
                schema = target;
            }
            schema
        }

        fn allows(&self, wanted: Type) -> bool {
            self.types.contains(&wanted)
        }

        fn property(&self, name: &str) -> Option<&'static Schema> {
            let (_, schema) = self.properties?.iter().find(|(known, _)| *known == name)?;
            Some(schema)
        }

        /// The type the schema asks for, as Zod words it in a message.
        fn expected(&self) -> &'static str {
            // With null: the other type.
            match self.types.iter().find(|allowed| **allowed != Type::Null) {
                Some(Type::Array) if self.prefix_items.is_some() => "tuple",
                Some(Type::Object) if self.properties.is_none() => "record",
                Some(allowed) => allowed.name(),
                // No type: anything, which a missing value is not.
                None => "nonoptional",
            }
        }
    }

    // -------------------------------------------------------------------------
    // Checking
    // -------------------------------------------------------------------------

    /// One thing a value got wrong.
    #[derive(Debug, Clone, PartialEq, Serialize)]
    struct Issue {
        /// Where: keys and indexes from the root of the part that was checked.
        path: Vec<Value>,
        /// What is wrong there.
        message: String,
        /// The kind of issue, named as Zod names it.
        code: &'static str,
    }

    /// The part of a request a schema describes.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum Part {
        Body,
        Query,
        Params,
    }

    impl Part {
        fn name(self) -> &'static str {
            match self {
                Part::Body => "body",
                Part::Query => "query",
                Part::Params => "params",
            }
        }

        fn prefix(self) -> &'static str {
            match self {
                Part::Body => "Validation error",
                Part::Query => "Query validation error",
                Part::Params => "Params validation error",
            }
        }

        /// Whether the values of the part arrive as text.
        fn is_text(self) -> bool {
            matches!(self, Part::Query | Part::Params)
        }
    }

    /// What Zod calls the type of a JSON value.
    fn kind_of(value: &Value) -> &'static str {
        match value {
            Value::Null => "null",
            Value::Bool(_) => "boolean",
            Value::Number(_) => "number",
            Value::String(_) => "string",
            Value::Array(_) => "array",
            Value::Object(_) => "object",
        }
    }

    /// The largest integer a JavaScript number holds exactly.
    const MAX_SAFE_INTEGER: f64 = 9_007_199_254_740_991.0;

    /// The integer a number is, if it is one that every side can hold.
    fn whole(number: f64) -> Option<i64> {
        let safe = number.fract() == 0.0 && number.abs() <= MAX_SAFE_INTEGER;
        // Checked above: the cast neither truncates nor wraps.
        #[allow(clippy::cast_possible_truncation)]
        safe.then_some(number as i64)
    }

    /// Reads a value's numbers as JavaScript does, which has one kind of
    /// number: 2.0 is the integer 2. Done once, before a value is checked,
    /// so that checking only reads and the typed value is built from what
    /// was checked. It holds everywhere in the value, also where the
    /// contract says nothing about a member: the TypeScript handlers see
    /// 2 there too.
    fn as_javascript(value: &mut Value) {
        match value {
            Value::Number(number) if number.is_f64() => {
                if let Some(integer) = number.as_f64().and_then(whole) {
                    *number = Number::from(integer);
                }
            }
            Value::Array(items) => items.iter_mut().for_each(as_javascript),
            Value::Object(members) => members.values_mut().for_each(as_javascript),
            _ => {}
        }
    }

    /// A number as JavaScript writes it: an integer has no fraction.
    fn js_number(number: f64) -> String {
        whole(number).map_or_else(|| number.to_string(), |integer| integer.to_string())
    }

    /// A JavaScript pattern as one this engine reads the same way.
    ///
    /// In JavaScript, without the u flag, the classes for digits and word
    /// characters and the word boundary are ASCII; here they are Unicode
    /// unless written out.
    fn from_javascript(pattern: &str) -> String {
        let mut out = String::with_capacity(pattern.len() + 8);
        let mut in_class = false;
        let mut chars = pattern.chars();
        while let Some(c) = chars.next() {
            match c {
                '\\' => match (chars.next(), in_class) {
                    (Some('d'), false) => out.push_str("[0-9]"),
                    (Some('w'), false) => out.push_str("[A-Za-z0-9_]"),
                    (Some('b'), false) => out.push_str("(?-u:\\b)"),
                    (Some('B'), false) => out.push_str("(?-u:\\B)"),
                    (Some('d'), true) => out.push_str("0-9"),
                    (Some('w'), true) => out.push_str("A-Za-z0-9_"),
                    // Also inside a class, where a class is a union.
                    (Some('D'), _) => out.push_str("[^0-9]"),
                    (Some('W'), _) => out.push_str("[^A-Za-z0-9_]"),
                    // In a class, a backspace.
                    (Some('b'), true) => out.push_str("\\x08"),
                    (Some(other), _) => {
                        out.push('\\');
                        out.push(other);
                    }
                    (None, _) => out.push('\\'),
                },
                '[' if !in_class => {
                    in_class = true;
                    out.push(c);
                }
                ']' if in_class => {
                    in_class = false;
                    out.push(c);
                }
                _ => out.push(c),
            }
        }
        out
    }

    /// A pattern of the contract: a regular expression as JavaScript reads
    /// it, compiled once.
    #[derive(Debug)]
    pub(super) struct Pattern {
        source: &'static str,
        compiled: OnceLock<Result<fancy_regex::Regex, String>>,
    }

    impl Pattern {
        pub(super) const fn new(source: &'static str) -> Self {
            Self {
                source,
                compiled: OnceLock::new(),
            }
        }

        /// The compiled pattern, or why it does not compile here.
        fn regex(&self) -> Result<&fancy_regex::Regex, &str> {
            let compiled = self.compiled.get_or_init(|| {
                fancy_regex::Regex::new(&from_javascript(self.source))
                    .map_err(|error| error.to_string())
            });
            compiled.as_ref().map_err(String::as_str)
        }

        /// Whether the text matches. Text the engine gives up on (it
        /// bounds how far it backtracks) does not match, and is reported.
        fn matches(&self, text: &str) -> bool {
            let Ok(regex) = self.regex() else {
                return false;
            };
            regex.is_match(text).unwrap_or_else(|error| {
                let pattern = self.source;
                tracing::warn!(pattern, %error, "a pattern could not be matched");
                false
            })
        }
    }

    /// Compiles every pattern of the contract, so that one this engine
    /// cannot read is found when the server starts and not by a request,
    /// which it would refuse whatever its value.
    ///
    /// Panics with the pattern if one does not compile.
    pub(super) fn compile(patterns: &[&Pattern]) {
        for pattern in patterns {
            if let Err(error) = pattern.regex() {
                let source = pattern.source;
                panic!("the pattern {source:?} of the contract does not compile: {error}");
            }
        }
    }

    /// A string format, as Zod names it in a message.
    fn format_noun(format: &str) -> &str {
        match format {
            "date-time" => "ISO datetime",
            "date" => "ISO date",
            "time" => "ISO time",
            "duration" => "ISO duration",
            "email" => "email address",
            "uuid" => "UUID",
            "uri" => "URL",
            "ipv4" => "IPv4 address",
            "ipv6" => "IPv6 address",
            other => other,
        }
    }

    /// Checks JSON values against a schema and collects what is wrong.
    #[derive(Default)]
    struct Checker {
        issues: Vec<Issue>,
        /// Where the value being checked is.
        path: Vec<Value>,
        /// Whether the values arrived as text (a query, a path).
        text: bool,
    }

    impl Checker {
        fn issue(&mut self, code: &'static str, message: impl Into<String>) {
            self.issues.push(Issue {
                path: self.path.clone(),
                message: message.into(),
                code,
            });
        }

        /// Whether the value fits the schema, without recording why not.
        fn fits(&self, schema: &'static Schema, value: &Value) -> bool {
            let mut probe = Checker {
                text: self.text,
                ..Checker::default()
            };
            probe.check(schema, Some(value));
            probe.issues.is_empty()
        }

        /// Checks the value at a member or an index.
        fn check_at(&mut self, key: Value, schema: &'static Schema, value: Option<&Value>) {
            self.path.push(key);
            self.check(schema, value);
            self.path.pop();
        }

        /// Checks a value and records what is wrong. The value is only
        /// read, so that trying an alternative costs no copy.
        fn check(&mut self, schema: &'static Schema, value: Option<&Value>) {
            let schema = schema.resolved();

            // A value that is listed: a missing one is not.
            if let Some(constant) = schema.constant {
                if !value.is_some_and(|value| constant.is(value)) {
                    let expected = constant.json();
                    self.issue(
                        "invalid_value",
                        format!("Invalid input: expected {expected}"),
                    );
                }
                return;
            }
            if let Some(options) = schema.options {
                if !value.is_some_and(|value| options.iter().any(|option| option.is(value))) {
                    let listed: Vec<String> = options.iter().map(|option| option.json()).collect();
                    let listed = listed.join("|");
                    self.issue(
                        "invalid_value",
                        format!("Invalid option: expected one of {listed}"),
                    );
                }
                return;
            }
            if let Some(alternatives) = schema.any_of {
                self.check_alternatives(schema, alternatives, value);
                return;
            }

            // Null beside one other type is that type, nullable; beside
            // several it is a union.
            let several = schema
                .types
                .iter()
                .filter(|allowed| **allowed != Type::Null)
                .count()
                > 1;
            let Some(value) = value else {
                if several {
                    self.issue("invalid_union", "Invalid input");
                } else {
                    let expected = schema.expected();
                    self.issue(
                        "invalid_type",
                        format!("Invalid input: expected {expected}, received undefined"),
                    );
                }
                return;
            };
            if let Some(parts) = schema.all_of {
                for part in parts {
                    self.check(part, Some(value));
                }
                return;
            }
            if !self.has_type(schema, value, several) {
                return;
            }

            match value {
                Value::String(text) => self.check_string(schema, text),
                Value::Number(number) => {
                    self.check_number(schema, number.as_f64().unwrap_or(f64::NAN));
                }
                Value::Array(items) => self.check_array(schema, items),
                Value::Object(members) => self.check_object(schema, members),
                Value::Null | Value::Bool(_) => {}
            }
        }

        /// Whether the value has a type the schema allows; records the
        /// issue if not.
        fn has_type(&mut self, schema: &Schema, value: &Value, several: bool) -> bool {
            if schema.types.is_empty() {
                return true;
            }
            let actual = kind_of(value);
            let integral = value.as_f64().is_some_and(|number| number.fract() == 0.0);
            let fits = schema.types.iter().any(|allowed| match allowed {
                Type::Integer => actual == "number" && integral,
                other => other.name() == actual,
            });
            if fits {
                return true;
            }
            if several {
                self.issue("invalid_union", "Invalid input");
                return false;
            }
            let expected = schema.expected();
            let numeric = schema.allows(Type::Integer) || schema.allows(Type::Number);
            let received = if schema.allows(Type::Integer) && actual == "number" {
                // The right kind and the wrong value.
                self.issue(
                    "invalid_type",
                    "Invalid input: expected int, received number",
                );
                return false;
            } else if self.text && numeric && actual == "string" {
                // Text that is not a number, read as a number.
                "NaN"
            } else {
                actual
            };
            self.issue(
                "invalid_type",
                format!("Invalid input: expected {expected}, received {received}"),
            );
            false
        }

        fn check_alternatives(
            &mut self,
            schema: &'static Schema,
            alternatives: &'static [Schema],
            value: Option<&Value>,
        ) {
            // T or null: what is wrong with a value that is not null is
            // what is wrong with it as a T.
            let mut others = alternatives
                .iter()
                .filter(|alternative| alternative.resolved().types != [Type::Null]);
            if let (Some(only), None, true) = (others.next(), others.next(), alternatives.len() > 1)
            {
                if !value.as_ref().is_some_and(|value| value.is_null()) {
                    self.check(only, value);
                }
                return;
            }

            // A member that tells the alternatives apart decides which
            // one the value is checked as. The contract names it.
            let Some(value) = value else {
                if schema.tag.is_some() {
                    self.issue(
                        "invalid_type",
                        "Invalid input: expected object, received undefined",
                    );
                } else {
                    self.issue("invalid_union", "Invalid input");
                }
                return;
            };
            if let Some(tag) = schema.tag {
                if !value.is_object() {
                    let actual = kind_of(value);
                    self.issue(
                        "invalid_type",
                        format!("Invalid input: expected object, received {actual}"),
                    );
                    return;
                }
                let constant = |alternative: &'static Schema| match alternative
                    .resolved()
                    .property(tag)?
                    .constant?
                {
                    Literal::Text(constant) => Some(constant),
                    _ => None,
                };
                let given = value.get(tag).and_then(Value::as_str);
                let chosen = alternatives
                    .iter()
                    .find(|alternative| given.is_some() && constant(alternative) == given);
                if let Some(alternative) = chosen {
                    self.check(alternative, Some(value));
                } else {
                    let listed: Vec<String> = alternatives
                        .iter()
                        .filter_map(constant)
                        .map(|constant| format!("'{constant}'"))
                        .collect();
                    let listed = listed.join(" | ");
                    self.path.push(Value::from(tag));
                    self.issue(
                        "invalid_union",
                        format!("Invalid discriminator value. Expected {listed}"),
                    );
                    self.path.pop();
                }
                return;
            }

            // Each alternative is tried once. One that fits has nothing to
            // report, so it is not checked a second time: in a union that
            // refers to itself that would double the work at every level.
            if !alternatives
                .iter()
                .any(|alternative| self.fits(alternative, value))
            {
                self.issue("invalid_union", "Invalid input");
            }
        }

        fn check_string(&mut self, schema: &Schema, text: &str) {
            // In code points, as Zod and JSON Schema count: neither bytes
            // nor what JavaScript's length gives outside the BMP.
            let length = u64::try_from(text.chars().count()).unwrap_or(u64::MAX);
            if let Some(minimum) = schema.min_length.filter(|minimum| length < *minimum) {
                self.issue(
                    "too_small",
                    format!("Too small: expected string to have >={minimum} characters"),
                );
            }
            if let Some(maximum) = schema.max_length.filter(|maximum| length > *maximum) {
                self.issue(
                    "too_big",
                    format!("Too big: expected string to have <={maximum} characters"),
                );
            }
            if let Some(pattern) = schema.pattern.filter(|pattern| !pattern.matches(text)) {
                // A format is written as a pattern; its name says what is
                // wrong.
                let message = if let Some(format) = schema.format {
                    format!("Invalid {}", format_noun(format))
                } else {
                    let source = pattern.source;
                    format!("Invalid string: must match pattern /{source}/")
                };
                self.issue("invalid_format", message);
            }
        }

        fn check_number(&mut self, schema: &Schema, amount: f64) {
            // The range of integers a JavaScript number holds exactly is
            // the bound of an int, not one the schema's author wrote.
            #[allow(clippy::float_cmp)]
            let what = |bound: f64| {
                if bound.abs() == MAX_SAFE_INTEGER {
                    "int"
                } else {
                    "number"
                }
            };
            if let Some(minimum) = schema.minimum.filter(|minimum| amount < *minimum) {
                let (what, minimum) = (what(minimum), js_number(minimum));
                self.issue(
                    "too_small",
                    format!("Too small: expected {what} to be >={minimum}"),
                );
            }
            if let Some(minimum) = schema
                .exclusive_minimum
                .filter(|minimum| amount <= *minimum)
            {
                let minimum = js_number(minimum);
                self.issue(
                    "too_small",
                    format!("Too small: expected number to be >{minimum}"),
                );
            }
            if let Some(maximum) = schema.maximum.filter(|maximum| amount > *maximum) {
                let (what, maximum) = (what(maximum), js_number(maximum));
                self.issue(
                    "too_big",
                    format!("Too big: expected {what} to be <={maximum}"),
                );
            }
            if let Some(maximum) = schema
                .exclusive_maximum
                .filter(|maximum| amount >= *maximum)
            {
                let maximum = js_number(maximum);
                self.issue(
                    "too_big",
                    format!("Too big: expected number to be <{maximum}"),
                );
            }
            let off_step = |step: &f64| {
                *step != 0.0 && ((amount / step) - (amount / step).round()).abs() > 1e-9
            };
            if let Some(step) = schema.multiple_of.filter(off_step) {
                let step = js_number(step);
                self.issue(
                    "not_multiple_of",
                    format!("Invalid number: must be a multiple of {step}"),
                );
            }
        }

        fn check_array(&mut self, schema: &Schema, items: &[Value]) {
            let count = u64::try_from(items.len()).unwrap_or(u64::MAX);
            if let Some(minimum) = schema.min_items.filter(|minimum| count < *minimum) {
                self.issue(
                    "too_small",
                    format!("Too small: expected array to have >={minimum} items"),
                );
            }
            if let Some(maximum) = schema.max_items.filter(|maximum| count > *maximum) {
                self.issue(
                    "too_big",
                    format!("Too big: expected array to have <={maximum} items"),
                );
            }
            // A tuple gives a schema per position; a list one for every item.
            for (index, item) in items.iter().enumerate() {
                let positioned = schema.prefix_items.and_then(|schemas| schemas.get(index));
                if let Some(schema) = positioned.or(schema.items) {
                    self.check_at(Value::from(index), schema, Some(item));
                }
            }
        }

        fn check_object(&mut self, schema: &Schema, members: &Map<String, Value>) {
            for (name, property) in schema.properties.into_iter().flatten() {
                match members.get(*name) {
                    Some(member) => self.check_at(Value::from(*name), property, Some(member)),
                    None if schema.required.contains(name) => {
                        self.check_at(Value::from(*name), property, None);
                    }
                    None => {}
                }
            }

            // Members the schema does not name: refused by a closed
            // object, checked by a mapping, ignored otherwise.
            match schema.additional {
                Additional::Ignored => {}
                Additional::Refused => {
                    let unknown: Vec<String> = members
                        .keys()
                        .filter(|name| schema.property(name).is_none())
                        .map(|name| format!("\"{name}\""))
                        .collect();
                    if !unknown.is_empty() {
                        let noun = if unknown.len() == 1 { "key" } else { "keys" };
                        let unknown = unknown.join(", ");
                        self.issue(
                            "unrecognized_keys",
                            format!("Unrecognized {noun}: {unknown}"),
                        );
                    }
                }
                Additional::Each(each) => {
                    for (name, member) in members {
                        if schema.property(name).is_none() {
                            self.check_at(Value::from(name.as_str()), each, Some(member));
                        }
                    }
                }
            }
        }
    }

    // -------------------------------------------------------------------------
    // Requests and responses
    // -------------------------------------------------------------------------

    /// The number a text is, as JavaScript reads it when it converts text
    /// to a number: blank text is 0, and 0x, 0o and 0b start a hexadecimal,
    /// octal or binary integer.
    fn number_from_text(text: &str) -> Option<Number> {
        let text = text.trim();
        if text.is_empty() {
            return Some(Number::from(0));
        }
        let radix = match text.get(..2) {
            Some("0x" | "0X") => Some(16),
            Some("0o" | "0O") => Some(8),
            Some("0b" | "0B") => Some(2),
            _ => None,
        };
        if let Some(radix) = radix {
            return u64::from_str_radix(&text[2..], radix)
                .ok()
                .map(Number::from);
        }
        // Rust also reads "inf" and "nan" as numbers; JavaScript does not.
        if text
            .chars()
            .any(|c| c.is_alphabetic() && !matches!(c, 'e' | 'E'))
        {
            return None;
        }
        let number = text.parse::<f64>().ok()?;
        whole(number)
            .map(Number::from)
            .or_else(|| Number::from_f64(number))
    }

    /// Query and path values arrive as text. Where the schema asks for a
    /// number, a boolean or a list, the text is turned into one before it
    /// is checked; text that is not one is left as it is and fails the
    /// check.
    fn from_text(schema: &'static Schema, value: Value) -> Value {
        let schema = schema.resolved();
        match value {
            Value::String(text) => {
                let numeric = schema.allows(Type::Integer) || schema.allows(Type::Number);
                if let Some(number) = numeric.then(|| number_from_text(&text)).flatten() {
                    return Value::Number(number);
                }
                match text.as_str() {
                    "true" if schema.allows(Type::Boolean) => Value::Bool(true),
                    "false" if schema.allows(Type::Boolean) => Value::Bool(false),
                    // One occurrence of a key that takes a list.
                    _ if schema.allows(Type::Array) => {
                        from_text(schema, Value::Array(vec![Value::String(text)]))
                    }
                    _ => Value::String(text),
                }
            }
            Value::Array(items) => match schema.items {
                Some(item) => Value::Array(
                    items
                        .into_iter()
                        .map(|value| from_text(item, value))
                        .collect(),
                ),
                None => Value::Array(items),
            },
            Value::Object(members) => Value::Object(
                members
                    .into_iter()
                    .map(|(name, member)| match schema.property(&name) {
                        Some(property) => {
                            let member = from_text(property, member);
                            (name, member)
                        }
                        None => (name, member),
                    })
                    .collect(),
            ),
            other => other,
        }
    }

    /// The answer to a request that fails validation: which part, and each
    /// issue, in the shape the TypeScript handlers use.
    fn invalid(part: Part, issues: &[Issue]) -> Response {
        let mut error = format!("{}: ", part.prefix());
        for (index, issue) in issues.iter().enumerate() {
            if index > 0 {
                error.push_str(", ");
            }
            for (depth, key) in issue.path.iter().enumerate() {
                if depth > 0 {
                    error.push('.');
                }
                // Writing to a String does not fail.
                let _ = match key.as_str() {
                    Some(name) => write!(error, "{name}"),
                    None => write!(error, "{key}"),
                };
            }
            if !issue.path.is_empty() {
                error.push_str(": ");
            }
            error.push_str(&issue.message);
        }
        let body = serde_json::json!({ "error": error, "in": part.name(), "issues": issues });
        (StatusCode::BAD_REQUEST, axum::Json(body)).into_response()
    }

    fn internal_error() -> Response {
        let body = serde_json::json!({ "error": "Internal Server Error" });
        (StatusCode::INTERNAL_SERVER_ERROR, axum::Json(body)).into_response()
    }

    /// A checked value as the type a handler receives.
    fn typed<T: DeserializeOwned>(
        part: Part,
        schema: &'static Schema,
        mut value: Option<Value>,
    ) -> Result<T, Box<Response>> {
        let mut checker = Checker {
            text: part.is_text(),
            ..Checker::default()
        };
        if let Some(value) = value.as_mut() {
            as_javascript(value);
        }
        checker.check(schema, value.as_ref());
        if !checker.issues.is_empty() {
            return Err(Box::new(invalid(part, &checker.issues)));
        }
        serde_json::from_value(value.unwrap_or(Value::Null)).map_err(|error| {
            // The schema accepted the value and the type did not: the two
            // were generated from the same contract and disagree.
            let part = part.name();
            tracing::error!(part, %error, "a value its schema accepts does not fit its type");
            Box::new(internal_error())
        })
    }

    /// Whether a body with this Content-Type is taken to be meant as JSON.
    /// No value and text/plain count: a client that sets no header sends a
    /// text body as text/plain.
    fn meant_as_json(content_type: Option<&str>) -> bool {
        let Some(content_type) = content_type else {
            return true;
        };
        let media = content_type.split(';').next().unwrap_or("").trim();
        let media = media.to_ascii_lowercase();
        media.is_empty()
            || media == "application/json"
            || media.ends_with("+json")
            || media == "text/plain"
    }

    /// The answer to a body that is not JSON.
    fn not_json(headers: &HeaderMap) -> Response {
        let content_type = headers
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok());
        if meant_as_json(content_type) {
            let body =
                serde_json::json!({ "error": "Invalid JSON body", "in": "json", "issues": [] });
            return (StatusCode::BAD_REQUEST, axum::Json(body)).into_response();
        }
        let content_type = content_type.unwrap_or_default();
        let body = serde_json::json!({
            "error": format!("Unsupported content type \"{content_type}\": the body has to be JSON"),
            "in": "content-type",
            "issues": [],
        });
        (StatusCode::UNSUPPORTED_MEDIA_TYPE, axum::Json(body)).into_response()
    }

    /// One operation of the contract: what it takes and what it answers.
    #[derive(Debug)]
    pub(super) struct Operation {
        /// The method and the path, for the log.
        pub(super) name: &'static str,
        pub(super) params: Option<&'static Schema>,
        pub(super) query: Option<&'static Schema>,
        pub(super) body: Option<&'static Schema>,
        pub(super) response: Option<&'static Schema>,
        /// The error bodies the operation declares, by status.
        pub(super) errors: &'static [(u16, &'static Schema)],
    }

    impl Operation {
        /// The path parameters as the type a handler receives.
        pub(super) fn params<T: DeserializeOwned>(
            &self,
            values: HashMap<String, String>,
        ) -> Result<T, Box<Response>> {
            let schema = self.params.unwrap_or(&Schema::ANY);
            let members = values
                .into_iter()
                .map(|(name, text)| (name, Value::String(text)))
                .collect();
            typed(
                Part::Params,
                schema,
                Some(from_text(schema, Value::Object(members))),
            )
        }

        /// The query string as the type a handler receives. A key that
        /// occurs several times is a list.
        pub(super) fn query<T: DeserializeOwned>(
            &self,
            pairs: Vec<(String, String)>,
        ) -> Result<T, Box<Response>> {
            let schema = self.query.unwrap_or(&Schema::ANY);
            let mut members = Map::new();
            for (name, text) in pairs {
                match members.get_mut(&name) {
                    Some(Value::Array(items)) => items.push(Value::String(text)),
                    Some(existing) => {
                        let first = existing.take();
                        *existing = Value::Array(vec![first, Value::String(text)]);
                    }
                    None => {
                        members.insert(name, Value::String(text));
                    }
                }
            }
            typed(
                Part::Query,
                schema,
                Some(from_text(schema, Value::Object(members))),
            )
        }

        /// The JSON body of a request as the type a handler receives.
        pub(super) fn body<T: DeserializeOwned>(
            &self,
            headers: &HeaderMap,
            bytes: &Bytes,
        ) -> Result<T, Box<Response>> {
            let text = String::from_utf8_lossy(bytes);
            let value = if text.trim().is_empty() {
                // No body: checked as a missing value.
                None
            } else {
                let value = serde_json::from_str(&text).map_err(|_| Box::new(not_json(headers)))?;
                Some(value)
            };
            typed(Part::Body, self.body.unwrap_or(&Schema::ANY), value)
        }

        /// What a handler returned, as the response.
        pub(super) fn respond<T: Serialize>(&self, value: &T) -> Response {
            self.answer(StatusCode::OK, self.response, value)
        }

        /// A failure outside the contract: logged here, answered as a 500
        /// that says nothing about it.
        pub(super) fn internal(&self, error: &super::InternalError) -> Response {
            let operation = self.name;
            tracing::error!(operation, %error, "a handler failed");
            internal_error()
        }

        /// An error a handler returned, as the response of that status.
        pub(super) fn fail<T: Serialize>(&self, status: StatusCode, body: &T) -> Response {
            let declared = self
                .errors
                .iter()
                .find(|(code, _)| *code == status.as_u16());
            self.answer(status, declared.map(|(_, schema)| *schema), body)
        }

        /// A value is checked against the schema of its status, then
        /// sent. One the schema rejects is a 500 and is logged, never sent.
        fn answer<T: Serialize>(
            &self,
            status: StatusCode,
            schema: Option<&'static Schema>,
            value: &T,
        ) -> Response {
            let operation = self.name;
            let json = match serde_json::to_value(value) {
                Ok(json) => json,
                Err(error) => {
                    tracing::error!(operation, %error, "the returned value cannot be written as JSON");
                    return internal_error();
                }
            };
            let mut checker = Checker::default();
            checker.check(schema.unwrap_or(&Schema::ANY), Some(&json));
            if !checker.issues.is_empty() {
                let issues = serde_json::to_string(&checker.issues).unwrap_or_default();
                tracing::error!(operation, %status, issues, "the returned value does not match its schema");
                return internal_error();
            }
            // Written from the value itself: its members in the order of
            // the type.
            (status, axum::Json(value)).into_response()
        }
    }

    /// Reads a member that may be absent and whose type has a value for
    /// null of its own: a null that is there is that value, not an absent
    /// member.
    pub(super) fn present_member<'de, T, D>(deserializer: D) -> Result<Option<T>, D::Error>
    where
        T: Deserialize<'de>,
        D: serde::Deserializer<'de>,
    {
        T::deserialize(deserializer).map(Some)
    }

    /// A default the contract gives as JSON, as the type of its member.
    pub(super) fn default_value<T: DeserializeOwned>(json: &str) -> T {
        serde_json::from_str(json).expect("a generated default fits its type")
    }
}
